const SRC_RETIRED=['corsair','elgato','shark','sandisk'];
const SEED_V=12;   /* bump when a seed row's status/note must overwrite what browsers already hold */
/* ---- FLOORS (b10): the customisable Filter & Sort, one set per source, shared. Applied after the rule, before the queue.
   Jack 13 Sep: "I might decide I only want Logitech doing 5,000+ sales per month" — that lives on the source, in one place. ---- */
const FLOORS=[['minSpm','Sales / month ≥','both'],['minRoi','ROI % ≥','both'],['minProfit','Profit £ ≥','both'],['minSell','Sell £ ≥','both'],['maxBuy','Buy £ ≤','both'],['minScore','Score ≥','both'],['minOffers','Offers ≥','r2']];
function leadNums(o,rule){return rule===1?{spm:o.SPM,roi:o['ROI %'],profit:o['Profit £'],sell:o['Sell £ used'],buy:o['Landed £'],score:o.Score==null?null:o.Score,offers:null}
  :{spm:o['Sells /mo'],roi:o['ROI %'],profit:o['Profit £'],sell:o['Sell for £'],buy:o['After discount £'],score:Math.max(o.Score||0,o['Potential score']||0),offers:o.Offers};}
/* '' when the lead passes, otherwise the floor it fails */
function failsFloor(o,f,rule){if(!f)return'';const n=leadNums(o,rule);const has=k=>f[k]!=null&&f[k]!==''&&!isNaN(+f[k]);
  if(has('minSpm')&&n.spm<+f.minSpm)return`sales ${n.spm}/mo < ${f.minSpm}`;
  if(has('minRoi')&&n.roi<+f.minRoi)return`ROI ${n.roi}% < ${f.minRoi}%`;
  if(has('minProfit')&&n.profit<+f.minProfit)return`profit £${n.profit} < £${f.minProfit}`;
  if(has('minSell')&&n.sell<+f.minSell)return`sell £${n.sell} < £${f.minSell}`;
  if(has('maxBuy')&&n.buy>+f.maxBuy)return`buy £${n.buy} > £${f.maxBuy}`;
  if(has('minScore')&&n.score!=null&&n.score<+f.minScore)return`score ${n.score} < ${f.minScore}`;
  if(has('minOffers')&&n.offers!=null&&n.offers<+f.minOffers)return`${n.offers} offers < ${f.minOffers}`;return'';}
function floorsLabel(f){if(!f)return'';return FLOORS.filter(([k])=>f[k]!=null&&f[k]!=='').map(([k,l])=>l.replace('≥','≥ ').replace('≤','≤ ')+(+f[k]).toLocaleString()).join(' · ');}
/* ---- never-sell categories (b17, Jack 14 Sep: alcohol full stop, fashion, shoes). Shared list; matched against the category
   tree and the title, whole words. A hit drops the lead on every rule, like the ASIN and brand blacklists. ---- */
