function settingRow(key,value){return{key,value,updated_at:nowIso(),updated_by:me()};}
function reasonsSave(list){lsSet(REASONS_KEY,list);cloudQueue('src_settings','upsert',[settingRow('reasons',list)]);}
function vat0Save(words){lsSet(VAT0_KEY,words);cloudQueue('src_settings','upsert',[settingRow('vat0',words)]);}
function me(){return lsGet(ME_KEY,'');}
function isJack(){return me()==='Jack';}
function verdAll(){return lsGet(VERD_KEY,{});}
function verdGet(asin){return verdAll()[asin]||null;}
/* v = {v:'Yes'|'No'|'Maybe', reason, note, source, state} — state is the lead's numbers at the moment of the verdict; that is what "better since" compares against */
function verdSet(asin,v){const a=verdAll();
  if(!v){delete a[asin];lsSet(VERD_KEY,a);cloudQueue('src_verdicts','delete',{col:'asin',vals:[asin]});return;}
  const row=Object.assign({at:nowIso(),who:me()},v);a[asin]=row;lsSet(VERD_KEY,a);
  cloudQueue('src_verdicts','upsert',[{asin,v:row.v,reason:row.reason||'',note:row.note||'',who:row.who||'',at:row.at,source_key:row.source||'',state:row.state||null}]);}
/* many at once (the "mark all as seen" baseline) — one queued write, not hundreds */
function verdSetMany(items){const a=verdAll();const at=nowIso(),who=me();const rows=[];
  items.forEach(({asin,v})=>{const row=Object.assign({at,who},v);a[asin]=row;rows.push({asin,v:row.v,reason:row.reason||'',note:row.note||'',who,at,source_key:row.source||'',state:row.state||null});});
  lsSet(VERD_KEY,a);cloudQueue('src_verdicts','upsert',rows);}

/* ---- ASIN facts: what a VA has confirmed about a product. Test-mode edition of the knowledge layer. ---- */
const FACT_KEY='bdl-sourcing-facts';
const PM_OPTIONS=['Currys','Argos','John Lewis','Brand direct'];
function factsAll(){return lsGet(FACT_KEY,{});}
function factGet(asin){return factsAll()[asin]||{};}
function factSet(asin,f){const a=factsAll();const clean=Object.assign({},a[asin]||{},f,{at:nowIso(),who:me()});
  Object.keys(clean).forEach(k=>{if(clean[k]==null||clean[k]==='')delete clean[k];});
  const empty=!(clean.pm&&clean.pm.length)&&!clean.sell&&!clean.note&&clean.vat==null&&!clean.track;
  if(empty){delete a[asin];lsSet(FACT_KEY,a);cloudQueue('src_facts','delete',{col:'asin',vals:[asin]});return;}
  a[asin]=clean;lsSet(FACT_KEY,a);const {who,at,...data}=clean;cloudQueue('src_facts','upsert',[{asin,data,who:who||'',at}]);}

