function blSet(asin,b){const a=blAll();const row=Object.assign({at:nowIso(),who:me()},b);a[asin]=row;lsSet(BL_KEY,a);
  cloudQueue('src_blacklist','upsert',[{asin,reason:row.reason,note:row.note||'',title:row.title||'',who:row.who||'',at:row.at,source_key:row.source||''}]);}
function blRemove(asin){const a=blAll();delete a[asin];lsSet(BL_KEY,a);cloudQueue('src_blacklist','delete',{col:'asin',vals:[asin]});}
/* ---- brand blacklist (b10): a VA requests it with a reason, Jack approves. Pending shows as a chip; approved drops the brand from every run. ---- */
const BB_KEY='bdl-sourcing-brandbl';
function bbAll(){return lsGet(BB_KEY,{});}
function bbKey(b){return(b||'').trim().toLowerCase();}
function bbRow(k,r){return{brand:k,display:r.display||k,reason:r.reason,requested_by:r.by||'',requested_at:r.at,status:r.status,decided_by:r.decidedBy||'',decided_at:r.decidedAt||null};}
function bbRequest(brand,reason,approveNow){const k=bbKey(brand);if(!k)return;const a=bbAll();
  a[k]={display:brand.trim(),reason,by:me(),at:nowIso(),status:approveNow?'approved':'pending',decidedBy:approveNow?me():'',decidedAt:approveNow?nowIso():''};lsSet(BB_KEY,a);cloudQueue('src_brand_blacklist','upsert',[bbRow(k,a[k])]);}
function bbDecide(k,status){const a=bbAll();if(!a[k])return;a[k].status=status;a[k].decidedBy=me();a[k].decidedAt=nowIso();lsSet(BB_KEY,a);cloudQueue('src_brand_blacklist','upsert',[bbRow(k,a[k])]);}
function bbRemove(k){const a=bbAll();delete a[k];lsSet(BB_KEY,a);cloudQueue('src_brand_blacklist','delete',{col:'brand',vals:[k]});}
/* 'approved' | 'pending' | null for a Keepa brand string ("Philips Sonicare" matches a blacklisted "Philips") */
function bbStatusFor(brand){const b=bbKey(brand);if(!b)return null;const a=bbAll();
  for(const k of Object.keys(a)){if(b===k||b.startsWith(k+' ')){if(a[k].status==='approved')return'approved';if(a[k].status==='pending')return'pending';}}return null;}

