const DISC_SEED=[{"name":"Acer","type":"brand","pct":15,"salePct":5,"fullPriceOnly":true,"verified":true},{"name":"AO","type":"retailer","flat":10,"minSpend":300,"verified":true,"note":"flat not pct - effective % falls as price rises"},{"name":"Argos","type":"retailer","pct":6,"verified":true},{"name":"B&Q","type":"retailer","pct":4,"verified":true},{"name":"Beauty Bay","type":"retailer","pct":15,"minSpend":50,"verified":true},{"name":"Boots","type":"retailer","pct":3,"verified":true,"note":"extra 10% on Bangers is IN-STORE ONLY - not usable for OA"},{"name":"Bosch","type":"brand","pct":10,"verified":true},{"name":"Currys","type":"retailer","pct":5,"verified":true},{"name":"De'Longhi","type":"brand","pct":10,"verified":true},{"name":"Dyson","type":"brand","pct":10,"fullPriceOnly":true,"verified":true},{"name":"e.l.f.","type":"brand","pct":20,"fullPriceOnly":true,"verified":true},{"name":"Gillette","type":"brand","pct":10,"fullPriceOnly":true,"verified":true,"note":"also via newsletter signup"},{"name":"Gtech","type":"brand","pct":19,"note":"Amazon Business tiers on the listing itself — Keepa never shows them (AirRAM: Keepa £168.99, Business 10 units £136.20 inc VAT = 19%). VA must open the listing on the Business account.","verified":true,"business":true},{"name":"Halfords","type":"retailer","pct":4,"verified":true},{"name":"Henry (Numatic)","type":"brand","pct":10,"verified":true},{"name":"Holland & Barrett","type":"retailer","note":"always has a code - rate varies, check at purchase"},{"name":"Honor","type":"brand","pct":10,"verified":true},{"name":"Hoover Direct","type":"brand","pct":15,"verified":true,"note":"Jack 12 Sep: use 15 to get the best COGs.  (two-item minimum)"},{"name":"Huawei","type":"brand","pct":15,"verified":true},{"name":"Huel","type":"brand","pct":10,"verified":true},{"name":"iHerb","type":"retailer"},{"name":"John Lewis","type":"retailer","pct":4,"verified":true},{"name":"Kenwood","type":"brand","note":"price-matched at most retailers — check Currys / JL","verified":false},{"name":"Lego","type":"brand","pct":5,"fullPriceOnly":true,"verified":true},{"name":"Lenovo","type":"brand","pct":10,"verified":true},{"name":"Logitech","type":"brand","note":"code via Honey/Coupert, rate varies"},{"name":"Marks Electrical","type":"retailer","pct":8,"verified":true,"note":"includes sale items"},{"name":"Miele","type":"brand","pct":10,"minSpend":300,"note":"NOT TESTED"},{"name":"Mirfama","type":"retailer"},{"name":"Ninja Kitchen","type":"brand","pct":9,"verified":true,"note":"includes sale items"},{"name":"OnePlus","type":"brand","pct":10,"verified":true},{"name":"Philips Home Appliances","type":"brand","pct":5,"verified":true},{"name":"Robert Dyas","type":"retailer","pct":5,"verified":true},{"name":"Russell Hobbs","type":"brand","pct":20,"verified":true},{"name":"Sage Appliances","type":"brand","pct":15,"minSpend":250,"note":"NOT TESTED"},{"name":"Samsung","type":"brand","pct":10,"verified":true,"note":"Samsung website only · UK monitors and TVs: Currys or Argos price-match most likely (Jack, 14 Sep)"},{"name":"Tassimo","type":"brand","pct":10,"verified":true,"note":"Bosch store 10% — only when it is on offer at Bosch; otherwise Argos or Currys price-match (Jack, 14 Sep). Pods are 0% VAT."},{"name":"Shark","type":"brand","pct":9,"verified":true,"note":"includes sale; also 10% via newsletter signup"},{"name":"Skinny Food Co","type":"brand"},{"name":"Sports Direct","type":"retailer","pct":3.5,"verified":true,"note":"delivery fee can exceed the discount on small orders"},{"name":"Stanley","type":"brand","pct":15,"verified":true},{"name":"Superdrug","type":"retailer","pct":10,"cap":5,"verified":true,"note":"CAPPED at £5 - effective rate falls below 10% above £50 spend; codes run out fast"},{"name":"Tefal","type":"brand","pct":10,"fullPriceOnly":true,"verified":true},{"name":"Tesco","type":"retailer","pct":3,"verified":true,"note":"local store"},{"name":"The Entertainer","type":"retailer","pct":5,"verified":true,"note":"TEMPORARY - reverts to 4%"},{"name":"The Perfume Shop","type":"retailer","pct":15,"verified":true},{"name":"Vax","type":"brand","pct":10,"verified":true},{"name":"Wahl","type":"brand","pct":15,"verified":true}];
function discAll(){let v=lsGet(DISC_KEY,null);if(!v||!v.length){v=DISC_SEED.map(x=>Object.assign({},x));lsSet(DISC_KEY,v);return v;}
  /* b23: seed rows added later (Tassimo) join an existing list once — only after the cloud copy is in, or the pull would wipe them */
  const ready=typeof cloudEnabled!=='function'||!cloudEnabled()||(typeof cloud!=='undefined'&&cloud.pulled);
  if(ready&&lsGet(DISC_KEY+'-seedv',1)<2){const ids=new Set(v.map(discId)),add=[];
    DISC_SEED.forEach(s=>{if(!ids.has(discId(s))){const e=Object.assign({},s);v.push(e);add.push(e);}});
    const sm=v.find(e=>discId(e)==='samsung'),ss=DISC_SEED.find(s=>s.name==='Samsung');if(sm&&ss&&sm.note==='Samsung website only'){sm.note=ss.note;add.push(sm);}
    lsSet(DISC_KEY+'-seedv',2);if(add.length){lsSet(DISC_KEY,v);if(typeof cloudQueue==='function')cloudQueue('src_discounts','upsert',add.map(discRow));}}
  return v;}
function discId(e){return(e.name||'').trim().toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');}
function discRow(e){return{id:discId(e),data:e,updated_at:nowIso(),updated_by:me()};}
function discSave(list){const old=discAll().map(discId);const now=new Set(list.map(discId));lsSet(DISC_KEY,list);
  cloudQueue('src_discounts','delete',{col:'id',vals:old.filter(id=>!now.has(id))});cloudQueue('src_discounts','upsert',list.map(discRow));}
function discReset(){const old=discAll().map(discId);localStorage.removeItem(DISC_KEY);const seed=discAll();
  cloudQueue('src_discounts','delete',{col:'id',vals:old.filter(id=>!seed.some(e=>discId(e)===id))});cloudQueue('src_discounts','upsert',seed.map(discRow));}
/* the brand's own channel for a product, if we have one */
function discForBrand(brand){const b=(brand||'').toLowerCase().trim();if(!b)return null;const w=b.split(/\s+/)[0];
  return discAll().find(e=>e.type==='brand'&&(e.name.toLowerCase()===b||e.name.toLowerCase().startsWith(w)||b.startsWith(e.name.toLowerCase().split(' ')[0])))||null;}
/* generic price-matchers: retailers that match Amazon then discount on top */
function discMatchers(){return discAll().filter(e=>e.type==='retailer'&&e.pct&&!e.fullPriceOnly&&['argos','currys','john lewis','ao','marks electrical','robert dyas'].includes(e.name.toLowerCase()));}
/* what a discount entry is worth on a sale-priced (price-matched) item, on a given cost */
function discRate(e,cost){if(!e)return 0;if(e.flat)return cost>=(e.minSpend||0)?Math.min(100,100*e.flat/cost):0;
  if(e.minSpend&&cost<e.minSpend)return 0;let p=e.fullPriceOnly?(e.salePct||0):(e.pct||0);
  if(e.cap&&cost*p/100>e.cap)p=100*e.cap/cost;return p;}
